package com.marketplace.notification;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.mongodb.repository.MongoRepository; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.time.Instant;
interface NotificationRepository extends JpaRepository<Notification,Long>{} interface NotificationLogRepository extends MongoRepository<NotificationLog,String>{} @RestController @RequestMapping("/api/notifications") class NotificationController {private final NotificationRepository notifications;private final NotificationLogRepository logs;NotificationController(NotificationRepository n,NotificationLogRepository l){notifications=n;logs=l;}record Request(@NotBlank String recipient,@NotBlank String channel,@NotBlank String message){}@PostMapping @Transactional ResponseEntity<Notification> create(@Valid @RequestBody Request r){var n=notifications.save(new Notification(r.recipient(),r.channel(),r.message()));logs.save(new NotificationLog(null,n.id,"NOTIFICATION_CREATED",n.status,Instant.now()));return ResponseEntity.created(URI.create("/api/notifications/"+n.id)).body(n);}@PostMapping("/{id}/send") @Transactional Notification send(@PathVariable Long id){var n=notifications.findById(id).orElseThrow();n.status="SENT";n=notifications.save(n);logs.save(new NotificationLog(null,n.id,"NOTIFICATION_SENT",n.channel,Instant.now()));return n;}}
